let user = { name: 'Alice' };

// 1. Regular Map (strong reference)
const strongMap = new Map();
strongMap.set(user, 'Data');

// 2. WeakMap (weak reference)
const weakMap = new WeakMap();
weakMap.set(user, 'Secret');

// Deleting the user object (breaking the reference)
user = null;

// Result:
// strongMap still holds Alice (memory not freed)
// weakMap releases Alice (collected by GC)
